    /** An area/zone with a y-range: a box (x1..x2, z1..z2) or a cylinder/ring around (cx, cz) with radius r0 (inner) .. r1. */
    public record Gebied3(String id, boolean cilinder, int a, int b, int c, int d, int minY, int maxY, int minLevel, int maxLevel,
                          boolean stad) {
        public static Gebied3 doos(String id, int x1, int z1, int x2, int z2, int y0, int y1, int lo, int hi, boolean stad) {
            return new Gebied3(id, false, Math.min(x1, x2), Math.min(z1, z2), Math.max(x1, x2), Math.max(z1, z2), y0, y1, lo, hi, stad);
        }

        public static Gebied3 doos(String id, int x1, int z1, int x2, int z2, int y0, int y1, int lo, int hi) {
            return doos(id, x1, z1, x2, z2, y0, y1, lo, hi, false);
        }

        public static Gebied3 cilinder(String id, int cx, int cz, int r0, int r1, int y0, int y1, int lo, int hi, boolean stad) {
            return new Gebied3(id, true, cx, cz, r0, r1, y0, y1, lo, hi, stad);
        }

        public static Gebied3 cilinder(String id, int cx, int cz, int r0, int r1, int y0, int y1, int lo, int hi) {
            return cilinder(id, cx, cz, r0, r1, y0, y1, lo, hi, false);
        }

        public boolean bevat(double x, double y, double z) {
            if (y < minY || y > maxY + 0.999) {
                return false;
            }
            if (!cilinder) {
                return x >= a && x <= c + 0.999 && z >= b && z <= d + 0.999;
            }
            double dx = x - (a + 0.5), dz = z - (b + 0.5), r2 = dx * dx + dz * dz;
            return r2 >= (double) c * c && r2 <= (double) d * d;
        }

        public String naamKey() {
            return "vadsrijk.kern.gebied." + id;
        }
    }

